61	  while (!timeSlots_.empty()) {
62	    if (timeSlots_[0].first.difference(now) <= WINDOW_TIME) {
63	      break;
64	    }
65	    bytesWindow_ -= timeSlots_[0].second;
66	    timeSlots_.pop_front();
67	  }
