117	  removeStaleTimeSlot(now);
118	  if (timeSlots_.empty() ||
119	      std::chrono::duration_cast<std::chrono::seconds>(
120	          timeSlots_.back().first.difference(now)) >= 1_s) {
121	    timeSlots_.push_back(std::make_pair(now, bytes));
122	  }
