97	DownloadEngine::DownloadEngine(std::unique_ptr<EventPoll> eventPoll)
98	    : eventPoll_(std::move(eventPoll)),
99	      haltRequested_(0),
100	      noWait_(true),
101	      refreshInterval_(DEFAULT_REFRESH_INTERVAL),
102	      lastRefresh_(Timer::zero()),
103	      cookieStorage_(make_unique<CookieStorage>()),
104	#ifdef ENABLE_BITTORRENT
105	      btRegistry_(make_unique<BtRegistry>()),
106	#endif // ENABLE_BITTORRENT
107	      dnsCache_(make_unique<DNSCache>()),
108	      option_(nullptr)
109	{
110	  unsigned char sessionId[20];
111	  util::generateRandomKey(sessionId);
112	  sessionId_.assign(&sessionId[0], &sessionId[sizeof(sessionId)]);
113	}
