117	namespace {
118	void executeCommand(std::deque<std::unique_ptr<Command>>& commands,
119	                    Command::STATUS statusFilter)
120	{
121	  size_t max = commands.size();
122	  for (size_t i = 0; i < max; ++i) {
123	    auto com = std::move(commands.front());
124	    commands.pop_front();
125	    if (!com->statusMatch(statusFilter)) {
126	      com->clearIOEvents();
127	      commands.push_back(std::move(com));
128	      continue;
129	    }
130	    com->transitStatus();
131	    if (com->execute()) {
132	      com.reset();
133	    }
134	    else {
135	      com->clearIOEvents();
136	      com.release();
137	    }
138	  }
139	}
140	} // namespace
141	
142	namespace {
143	class GlobalHaltRequestedFinalizer {
144	public:
145	  GlobalHaltRequestedFinalizer(bool oneshot) : oneshot_(oneshot) {}
146	  ~GlobalHaltRequestedFinalizer()
147	  {
148	    if (!oneshot_) {
149	      global::globalHaltRequested = 5;
150	    }
151	  }
152	
153	private:
154	  bool oneshot_;
155	};
156	} // namespace
157	
158	int DownloadEngine::run(bool oneshot)
159	{
160	  GlobalHaltRequestedFinalizer ghrf(oneshot);
161	  while (!commands_.empty() || !routineCommands_.empty()) {
162	    if (!commands_.empty()) {
163	      waitData();
164	    }
165	    noWait_ = false;
166	    global::wallclock().reset();
167	    calculateStatistics();
168	    if (lastRefresh_.difference(global::wallclock()) + A2_DELTA_MILLIS >=
169	        refreshInterval_) {
170	      refreshInterval_ = DEFAULT_REFRESH_INTERVAL;
171	      lastRefresh_ = global::wallclock();
172	      executeCommand(commands_, Command::STATUS_ALL);
173	    }
174	    else {
175	      executeCommand(commands_, Command::STATUS_ACTIVE);
176	    }
177	    executeCommand(routineCommands_, Command::STATUS_ALL);
178	    afterEachIteration();
179	    if (!noWait_ && oneshot) {
180	      return 1;
181	    }
182	  }
183	  onEndOfRun();
184	  return 0;
185	}
186	
187	void DownloadEngine::waitData()
188	{
189	  struct timeval tv;
190	  if (noWait_) {
191	    tv.tv_sec = tv.tv_usec = 0;
192	  }
193	  else {
194	    auto t =
195	        std::chrono::duration_cast<std::chrono::microseconds>(refreshInterval_);
196	    tv.tv_sec = t.count() / 1000000;
197	    tv.tv_usec = t.count() % 1000000;
198	  }
199	  eventPoll_->poll(tv);
200	}
