432	{
433	  std::pair<std::multimap<std::string, SocketPoolEntry>::iterator,
434	            std::multimap<std::string, SocketPoolEntry>::iterator>
435	      range = socketPool_.equal_range(key);
436	  for (auto i = range.first, eoi = range.second; i != eoi; ++i) {
437	    const SocketPoolEntry& e = (*i).second;
438	    // We assume that if socket is readable it means peer shutdowns
439	    // connection and the socket will receive EOF. So skip it.
440	    if (!e.isTimeout() && !e.getSocket()->isReadable(0)) {
441	      A2_LOG_INFO(fmt("Found socket for %s", key.c_str()));
442	      return i;
443	    }
444	  }
445	  return socketPool_.end();
