199	  }
200	  bool segmentPartComplete = false;
201	  // Note that GrowSegment::complete() always returns false.
202	  if (sinkFilterOnly_) {
203	    if (segment->complete() ||
204	        (getFileEntry()->getLength() != 0 &&
205	         segment->getPositionToWrite() == getFileEntry()->getLastOffset())) {
206	      segmentPartComplete = true;
207	    }
208	    else if (segment->getLength() == 0 && eof) {
209	      segmentPartComplete = true;
210	    }
211	  }
212	  else {
213	    int64_t loff = getFileEntry()->gtoloff(segment->getPositionToWrite());
214	    if (getFileEntry()->getLength() > 0 && !sinkFilterOnly_ &&
215	        ((loff == getRequestEndOffset() && streamFilter_->finished()) ||
216	         loff < getRequestEndOffset()) &&
217	        (segment->complete() ||
218	         segment->getPositionToWrite() == getFileEntry()->getLastOffset())) {
219	      // In this case, StreamFilter other than *SinkStreamFilter is
220	      // used and Content-Length is known.  We check
221	      // streamFilter_->finished() only if the requested end offset
222	      // equals to written position in file local offset; in other
223	      // words, data in the requested range is all received.  If
224	      // requested end offset is greater than this segment, then
225	      // streamFilter_ is not finished in this segment.
226	      segmentPartComplete = true;
227	    }
228	    else if (streamFilter_->finished()) {
229	      segmentPartComplete = true;
230	    }
231	  }
232	
233	  if (!segmentPartComplete && eof) {
234	    throw DL_RETRY_EX(EX_GOT_EOF);
235	  }
236	
237	  if (segmentPartComplete) {
238	    if (segment->complete() || segment->getLength() == 0) {
239	      // If segment->getLength() == 0, the server doesn't provide
240	      // content length, but the client detected that download
241	      // completed.
242	      A2_LOG_INFO(fmt(MSG_SEGMENT_DOWNLOAD_COMPLETED, getCuid()));
243	
244	      {
245	        const std::string& expectedPieceHash =
246	            getDownloadContext()->getPieceHash(segment->getIndex());
247	        if (pieceHashValidationEnabled_ && !expectedPieceHash.empty()) {
248	          if (
249	#ifdef ENABLE_BITTORRENT
250	              // TODO Is this necessary?
251	              (!getPieceStorage()->isEndGame() ||
252	               !getDownloadContext()->hasAttribute(CTX_ATTR_BT)) &&
253	#endif // ENABLE_BITTORRENT
254	              segment->isHashCalculated()) {
255	            A2_LOG_DEBUG(fmt("Hash is available! index=%lu",
256	                             static_cast<unsigned long>(segment->getIndex())));
257	            validatePieceHash(segment, expectedPieceHash, segment->getDigest());
258	          }
259	          else {
260	            try {
261	              std::string actualHash =
262	                  segment->getPiece()->getDigestWithWrCache(
263	                      segment->getSegmentLength(), diskAdaptor);
264	              validatePieceHash(segment, expectedPieceHash, actualHash);
265	            }
266	            catch (RecoverableException& e) {
267	              segment->clear(getPieceStorage()->getWrDiskCache());
268	              getSegmentMan()->cancelSegment(getCuid());
269	              throw;
270	            }
271	          }
272	        }
273	        else {
274	          completeSegment(getCuid(), segment);
275	        }
276	      }
277	    }
278	    else {
279	      // If segment is not canceled here, in the next pipelining
280	      // request, aria2 requests bad range
281	      // [FileEntry->getLastOffset(), FileEntry->getLastOffset())
282	      getSegmentMan()->cancelSegment(getCuid(), segment);
283	    }
284	    checkLowestDownloadSpeed();
285	    // this unit is going to download another segment.
286	    return prepareForNextSegment();
287	  }
288	  else {
289	    checkLowestDownloadSpeed();
290	    setWriteCheckSocketIf(getSocket(), shouldEnableWriteCheck());
291	    checkSocketRecvBuffer();
292	    addCommandSelf();
293	    return false;
294	  }
295	}
296	
297	bool DownloadCommand::shouldEnableWriteCheck()
298	{
299	  return getSocket()->wantWrite();
300	}
301	
302	void DownloadCommand::checkLowestDownloadSpeed() const
303	{
304	  if (lowestDownloadSpeedLimit_ > 0 &&
305	      peerStat_->getDownloadStartTime().difference(global::wallclock()) >=
306	          startupIdleTime_) {
307	    int nowSpeed = peerStat_->calculateDownloadSpeed();
308	    if (nowSpeed <= lowestDownloadSpeedLimit_) {
309	      throw DL_ABORT_EX2(fmt(EX_TOO_SLOW_DOWNLOAD_SPEED, nowSpeed,
310	                             lowestDownloadSpeedLimit_,
311	                             getRequest()->getHost().c_str()),
312	                         error_code::TOO_SLOW_DOWNLOAD_SPEED);
313	    }
314	  }
315	}
316	
317	bool DownloadCommand::prepareForNextSegment()
318	{
319	  if (getRequestGroup()->downloadFinished()) {
320	    // Remove in-flight request here.
321	    getFileEntry()->poolRequest(getRequest());
322	    // If this is a single file download, and file size becomes known
323	    // just after downloading, set total length to FileEntry object
324	    // here.
325	    if (getDownloadContext()->getFileEntries().size() == 1) {
326	      if (getFileEntry()->getLength() == 0) {
327	        getFileEntry()->setLength(getPieceStorage()->getCompletedLength());
328	      }
329	    }
330	    if (getDownloadContext()->getPieceHashType().empty()) {
331	      auto entry = make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
332	      if (entry->isValidationReady()) {
333	        entry->initValidator();
334	        entry->cutTrailingGarbage();
335	        getDownloadEngine()->getCheckIntegrityMan()->pushEntry(
336	            std::move(entry));
337	      }
338	    }
339	    // Following 2lines are needed for DownloadEngine to detect
340	    // completed RequestGroups without 1sec delay.
341	    getDownloadEngine()->setNoWait(true);
342	    getDownloadEngine()->setRefreshInterval(std::chrono::milliseconds(0));
343	    return true;
344	  }
345	  else {
346	    // The number of segments should be 1 in order to pass through the next
347	    // segment.
348	    if (getSegments().size() == 1) {
349	      std::shared_ptr<Segment> tempSegment = getSegments().front();
350	      if (!tempSegment->complete()) {
351	        return prepareForRetry(0);
352	      }
353	      if (getRequestEndOffset() ==
354	          getFileEntry()->gtoloff(tempSegment->getPosition() +
355	                                  tempSegment->getLength())) {
356	        return prepareForRetry(0);
357	      }
358	      std::shared_ptr<Segment> nextSegment =
359	          getSegmentMan()->getSegmentWithIndex(getCuid(),
360	                                               tempSegment->getIndex() + 1);
361	      if (!nextSegment) {
362	        nextSegment = getSegmentMan()->getCleanSegmentIfOwnerIsIdle(
363	            getCuid(), tempSegment->getIndex() + 1);
364	      }
365	      if (!nextSegment || nextSegment->getWrittenLength() > 0) {
366	        // If nextSegment->getWrittenLength() > 0, current socket must
367	        // be closed because writing incoming data at
368	        // nextSegment->getWrittenLength() corrupts file.
369	        return prepareForRetry(0);
370	      }
371	      else {
372	        checkSocketRecvBuffer();
373	        addCommandSelf();
374	        return false;
375	      }
376	    }
377	    else {
378	      return prepareForRetry(0);
379	    }
380	  }
381	}
382	
383	void DownloadCommand::validatePieceHash(const std::shared_ptr<Segment>& segment,
384	                                        const std::string& expectedHash,
385	                                        const std::string& actualHash)
386	{
387	  if (actualHash == expectedHash) {
388	    A2_LOG_INFO(fmt(MSG_GOOD_CHUNK_CHECKSUM, util::toHex(actualHash).c_str()));
389	    completeSegment(getCuid(), segment);
390	  }
391	  else {
392	    A2_LOG_INFO(fmt(EX_INVALID_CHUNK_CHECKSUM,
393	                    static_cast<unsigned long>(segment->getIndex()),
394	                    segment->getPosition(), util::toHex(expectedHash).c_str(),
395	                    util::toHex(actualHash).c_str()));
396	    segment->clear(getPieceStorage()->getWrDiskCache());
397	    getSegmentMan()->cancelSegment(getCuid());
398	    throw DL_RETRY_EX(fmt("Invalid checksum index=%lu",
399	                          static_cast<unsigned long>(segment->getIndex())));
400	  }
401	}
402	
403	void DownloadCommand::completeSegment(cuid_t cuid,
404	                                      const std::shared_ptr<Segment>& segment)
405	{
406	  flushWrDiskCacheEntry(getPieceStorage()->getWrDiskCache(), segment);
407	  getSegmentMan()->completeSegment(cuid, segment);
408	}
409	
410	void DownloadCommand::installStreamFilter(
411	    std::unique_ptr<StreamFilter> streamFilter)
412	{
413	  if (!streamFilter) {
414	    return;
415	  }
416	  streamFilter->installDelegate(std::move(streamFilter_));
417	  streamFilter_ = std::move(streamFilter);
418	  const std::string& name = streamFilter_->getName();
419	  sinkFilterOnly_ = util::endsWith(name, SinkStreamFilter::NAME);
420	}
