102	void printSizeProgress(ColorizedStream& o,
103	                       const std::shared_ptr<RequestGroup>& rg,
104	                       const TransferStat& stat,
105	                       const SizeFormatter& sizeFormatter)
106	{
107	#ifdef ENABLE_BITTORRENT
108	  if (rg->isSeeder()) {
109	    o << "SEED(";
110	    if (rg->getCompletedLength() > 0) {
111	      std::streamsize oldprec = o.precision();
112	      o << std::fixed << std::setprecision(1)
113	        << ((stat.allTimeUploadLength * 10) / rg->getCompletedLength()) / 10.0
114	        << std::setprecision(oldprec) << std::resetiosflags(std::ios::fixed);
115	    }
116	    else {
117	      o << "--";
118	    }
119	    o << ")";
120	  }
121	  else
122	#endif // ENABLE_BITTORRENT
123	  {
124	    o << sizeFormatter(rg->getCompletedLength()) << "B/"
125	      << sizeFormatter(rg->getTotalLength()) << "B";
126	    if (rg->getTotalLength() > 0) {
127	      o << colors::cyan << "("
128	        << 100 * rg->getCompletedLength() / rg->getTotalLength() << "%)";
129	      o << colors::clear;
130	    }
131	  }
132	}
