136	void printProgressCompact(ColorizedStream& o, const DownloadEngine* e,
137	                          const SizeFormatter& sizeFormatter)
138	{
139	  if (!e->getRequestGroupMan()->downloadFinished()) {
140	    NetStat& netstat = e->getRequestGroupMan()->getNetStat();
141	    int dl = netstat.calculateDownloadSpeed();
142	    int ul = netstat.calculateUploadSpeed();
143	    o << colors::magenta << "[" << colors::clear << "DL:" << colors::green
144	      << sizeFormatter(dl) << "B" << colors::clear;
145	    if (ul) {
146	      o << " UL:" << colors::cyan << sizeFormatter(ul) << "B" << colors::clear;
147	    }
148	    o << colors::magenta << "]" << colors::clear;
149	  }
150	
151	  const RequestGroupList& groups = e->getRequestGroupMan()->getRequestGroups();
152	  size_t cnt = 0;
153	  const size_t MAX_ITEM = 5;
154	  for (auto i = groups.begin(), eoi = groups.end(); i != eoi && cnt < MAX_ITEM;
155	       ++i, ++cnt) {
156	    const std::shared_ptr<RequestGroup>& rg = *i;
157	    TransferStat stat = rg->calculateStat();
158	    o << colors::magenta << "[" << colors::clear << "#"
159	      << GroupId::toAbbrevHex(rg->getGID()) << " ";
160	    printSizeProgress(o, rg, stat, sizeFormatter);
161	    o << colors::magenta << "]" << colors::clear;
162	  }
163	  if (cnt < groups.size()) {
164	    o << "(+" << groups.size() - cnt << ")";
165	  }
166	}
