170	void printProgress(ColorizedStream& o, const std::shared_ptr<RequestGroup>& rg,
171	                   const DownloadEngine* e, const SizeFormatter& sizeFormatter)
172	{
173	  TransferStat stat = rg->calculateStat();
174	  int eta = 0;
175	  if (rg->getTotalLength() > 0 && stat.downloadSpeed > 0) {
176	    eta =
177	        (rg->getTotalLength() - rg->getCompletedLength()) / stat.downloadSpeed;
178	  }
179	  o << colors::magenta << "[" << colors::clear << "#"
180	    << GroupId::toAbbrevHex(rg->getGID()) << " ";
181	  printSizeProgress(o, rg, stat, sizeFormatter);
182	  o << " CN:" << rg->getNumConnection();
183	#ifdef ENABLE_BITTORRENT
184	  auto btObj = e->getBtRegistry()->get(rg->getGID());
185	  if (btObj) {
186	    const PeerSet& peers = btObj->peerStorage->getUsedPeers();
187	    o << " SD:" << countSeeder(peers.begin(), peers.end());
188	  }
189	#endif // ENABLE_BITTORRENT
190	
191	  if (!rg->downloadFinished()) {
192	    o << " DL:" << colors::green << sizeFormatter(stat.downloadSpeed) << "B"
193	      << colors::clear;
194	  }
195	  if (stat.sessionUploadLength > 0) {
196	    o << " UL:" << colors::cyan << sizeFormatter(stat.uploadSpeed) << "B"
197	      << colors::clear;
198	    o << "(" << sizeFormatter(stat.allTimeUploadLength) << "B)";
199	  }
200	  if (eta > 0) {
201	    o << " ETA:" << colors::yellow << util::secfmt(eta) << colors::clear;
202	  }
203	  o << colors::magenta << "]" << colors::clear;
204	}
