239	void printProgressSummary(const RequestGroupList& groups, size_t cols,
240	                          const DownloadEngine* e,
241	                          const SizeFormatter& sizeFormatter)
242	{
243	  const char SEP_CHAR = '=';
244	  time_t now;
245	  time(&now);
246	  std::stringstream o;
247	  o << " *** Download Progress Summary";
248	  {
249	    time_t now;
250	    struct tm* staticNowtmPtr;
251	    char buf[26];
252	    if (time(&now) != (time_t)-1 &&
253	        (staticNowtmPtr = localtime(&now)) != nullptr &&
254	        asctime_r(staticNowtmPtr, buf) != nullptr) {
255	      char* lfptr = strchr(buf, '\n');
256	      if (lfptr) {
257	        *lfptr = '\0';
258	      }
259	      o << " as of " << buf;
260	    }
261	  }
262	  o << " *** \n"
263	    << std::setfill(SEP_CHAR) << std::setw(cols) << SEP_CHAR << "\n";
264	  global::cout()->write(o.str().c_str());
265	  std::for_each(groups.begin(), groups.end(),
266	                PrintSummary(cols, e, sizeFormatter));
