270	ConsoleStatCalc::ConsoleStatCalc(std::chrono::seconds summaryInterval,
271	                                 bool colorOutput, bool humanReadable)
272	    : summaryInterval_(std::move(summaryInterval)),
273	      readoutVisibility_(true),
274	      truncate_(true),
275	#ifdef __MINGW32__
276	      isTTY_(true),
277	#else  // !__MINGW32__
278	      isTTY_(isatty(STDOUT_FILENO) == 1),
279	#endif // !__MINGW32__
280	      colorOutput_(colorOutput)
281	{
282	  if (humanReadable) {
283	    sizeFormatter_ = make_unique<AbbrevSizeFormatter>();
284	  }
285	  else {
286	    sizeFormatter_ = make_unique<PlainSizeFormatter>();
287	  }
288	}
289	
290	void ConsoleStatCalc::calculateStat(const DownloadEngine* e)
291	{
292	  if (cp_.difference(global::wallclock()) + A2_DELTA_MILLIS <
293	      std::chrono::milliseconds(1000)) {
294	    return;
295	  }
296	  cp_ = global::wallclock();
297	  const SizeFormatter& sizeFormatter = *sizeFormatter_.get();
298	
299	  // Some terminals (e.g., Windows terminal) prints next line when the
300	  // character reached at the last column.
301	  unsigned short int cols = 79;
302	
303	  if (isTTY_) {
304	#ifndef __MINGW32__
305	#  ifdef HAVE_TERMIOS_H
306	    struct winsize size;
307	    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &size) == 0) {
308	      cols = std::max(0, (int)size.ws_col - 1);
309	    }
310	#  endif // HAVE_TERMIOS_H
311	#else    // __MINGW32__
312	    CONSOLE_SCREEN_BUFFER_INFO info;
313	    if (::GetConsoleScreenBufferInfo(::GetStdHandle(STD_OUTPUT_HANDLE),
314	                                     &info)) {
315	      cols = std::max(0, info.dwSize.X - 2);
316	    }
317	#endif   // !__MINGW32__
318	    std::string line(cols, ' ');
319	    global::cout()->printf("\r%s\r", line.c_str());
320	  }
321	  ColorizedStream o;
322	  if (e->getRequestGroupMan()->countRequestGroup() > 0) {
323	    if ((summaryInterval_ > 0_s) &&
324	        lastSummaryNotified_.difference(global::wallclock()) +
325	                A2_DELTA_MILLIS >=
326	            summaryInterval_) {
327	      lastSummaryNotified_ = global::wallclock();
328	      printProgressSummary(e->getRequestGroupMan()->getRequestGroups(), cols, e,
329	                           sizeFormatter);
330	      global::cout()->write("\n");
331	      global::cout()->flush();
332	    }
333	  }
334	  if (!readoutVisibility_) {
335	    return;
336	  }
337	  size_t numGroup = e->getRequestGroupMan()->countRequestGroup();
338	  const bool color = global::cout()->supportsColor() && isTTY_ && colorOutput_;
339	  if (numGroup == 1) {
340	    const std::shared_ptr<RequestGroup>& rg =
341	        *e->getRequestGroupMan()->getRequestGroups().begin();
342	    printProgress(o, rg, e, sizeFormatter);
343	  }
344	  else if (numGroup > 1) {
345	    // For more than 2 RequestGroups, use compact readout form
346	    printProgressCompact(o, e, sizeFormatter);
347	  }
348	
349	  {
350	    auto& entry = e->getFileAllocationMan()->getPickedEntry();
351	    if (entry) {
352	      o << " [FileAlloc:#"
353	        << GroupId::toAbbrevHex(entry->getRequestGroup()->getGID()) << " "
354	        << sizeFormatter(entry->getCurrentLength()) << "B/"
355	        << sizeFormatter(entry->getTotalLength()) << "B(";
356	      if (entry->getTotalLength() > 0) {
357	        o << 100LL * entry->getCurrentLength() / entry->getTotalLength();
358	      }
359	      else {
360	        o << "--";
361	      }
362	      o << "%)]";
363	      if (e->getFileAllocationMan()->hasNext()) {
364	        o << "(+" << e->getFileAllocationMan()->countEntryInQueue() << ")";
365	      }
366	    }
367	  }
368	  {
369	    auto& entry = e->getCheckIntegrityMan()->getPickedEntry();
370	    if (entry) {
371	      o << " [Checksum:#"
372	        << GroupId::toAbbrevHex(entry->getRequestGroup()->getGID()) << " "
373	        << sizeFormatter(entry->getCurrentLength()) << "B/"
374	        << sizeFormatter(entry->getTotalLength()) << "B(";
375	      if (entry->getTotalLength() > 0) {
376	        o << 100LL * entry->getCurrentLength() / entry->getTotalLength();
377	      }
378	      else {
379	        o << "--";
380	      }
381	      o << "%)]";
382	      if (e->getCheckIntegrityMan()->hasNext()) {
383	        o << "(+" << e->getCheckIntegrityMan()->countEntryInQueue() << ")";
384	      }
385	    }
386	  }
387	  if (isTTY_) {
388	    if (truncate_) {
389	      auto str = o.str(color, cols);
390	      global::cout()->write(str.c_str());
391	    }
392	    else {
393	      auto str = o.str(color);
394	      global::cout()->write(str.c_str());
395	    }
396	    global::cout()->flush();
397	  }
398	  else {
399	    auto str = o.str(false);
400	    global::cout()->write(str.c_str());
401	    global::cout()->write("\n");
402	  }
403	}
