void DefaultBtMessageDispatcher::sendMessagesInternal()
{
  auto tempQueue = std::vector<std::unique_ptr<BtMessage>>{};
  while (!messageQueue_.empty()) {
    auto msg = std::move(messageQueue_.front());
    messageQueue_.pop_front();
